const NOT_BODY=[
["part", 1, "TITRE UN : FORME - OBJET - DENOMINATION - SIEGE - DUREE"],
["art", 1, "ARTICLE UN : FORME"],
["p", 1, "Il est formé entre les soussignés, une Société à Responsabilité Limitée qui sera régie par l’Acte Uniforme de l’OHADA relatif au droit des Sociétés Commerciales et du Groupement d’Intérêt Economique (GIE) adoptés le trente Janvier deux mil quatorze, et par toutes autres dispositions légales et réglementaires complémentaires ou modificatives et par les présents Statuts."],
["art", 2, "ARTICLE DEUX : OBJET"],
["p", 2, "La société a pour objet, directement et indirectement en tous pays et plus particulièrement en République de COTE D’IVOIRE :"],
["ins", 2, "objet"],
["li", 2, "La prise de participation dans toutes les entreprises ou sociétés ivoiriennes ou étrangères, créées ou à créer ayant un objet similaire ou connexe;"],
["li", 2, "Et généralement, toutes opérations techniques, commerciales, financières, industrielles, mobilières et immobilières se rattachant directement ou indirectement à l’objet ci-dessus ou à tous autres objets similaires ou connexes et susceptibles d’en faciliter l’extension et le développement."],
["art", 3, "ARTICLE TROIS : DENOMINATION"],
["p", 3, "La société prend la dénomination de « »."],
["p", 3, "La dénomination sociale doit figurer sur tous les actes et documents émanant de la Société et destinés aux tiers, notamment les lettres, les factures, les annonces et publications diverses."],
["p", 3, "Elle doit être précédée ou suivie immédiatement en caractères lisibles des mots « Société à Responsabilité Limitée » ou du sigle « SARL », du montant de son capital social, de l’adresse de son siège social et de la mention de son immatriculation au Registre du Commerce et du Crédit Mobilier."],
["art", 4, "ARTICLE QUATRE : SIEGE"],
["p", 4, "Le siège social est fixé à ABIDJAN, Commune de, Quartier, BP"],
["p", 4, "Il pourra être transféré en tout autre endroit de la même ville par simple décision de la gérance, et partout ailleurs en vertu d’une décision collective extraordinaire des associés."],
["art", 5, "ARTICLE CINQ : DUREE"],
["p", 5, "La durée de la société est fixée à QUATRE VINGT DIX NEUF (99) ans à compter de la date d’immatriculation de la Société au Registre du Commerce et du Crédit Mobilier, sauf les cas de dissolution anticipée ou de prorogation prévue aux présents statuts."],
["part", 6, "TITRE DEUX : APPORTS - CAPITAL SOCIAL - AUGMENTATION - REDUCTION DU CAPITAL - PARTS SOCIALES - DROITS DES ASSOCIES"],
["art", 6, "ARTICLE SIX : APPORTS"],
["p", 6, "Les parts sociales doivent être souscrites en totalité. Elles doivent être intégralement libérées lorsqu’elles représentent des apports en nature."],
["p", 6, "Les parts représentant des apports en numéraire sont libérées lors de la constitution du capital de la moitié au moins de leur valeur nominale."],
["p", 6, "La libération du surplus intervient en une ou plusieurs fois dans un délai de deux (02) ans à compter de l’immatriculation de la société au Registre du Commerce et du Crédit Mobilier, selon les modalités définies par les statuts."],
["p", 6, "Les associés font apport à la présente société des sommes en numéraire ci-après, savoir :"],
["li", 6, "Monsieur, la somme de FRANCS CFA, ci.…………………………………………………………………………….… FCFA"],
["li", 6, "Monsieur, la somme de FRANCS CFA, ci.…………………...……………………….………………. FCFA"],
["p", 6, "TOTAL des apports en numéraire :"],
["p", 6, "la somme de de FRANCS CFA, ci..................................…..… FCFA"],
["p", 6, "Laquelle somme a été déposée pour le compte de la société à la comptabilité de Maître KOFFI-ABOUT A. Mireille, Notaire soussigné ainsi qu’il est constaté dans la Déclaration Notariée de Souscription et de Versement reçue par elle, ce jour."],
["art", 7, "ARTICLE SEPT : CAPITAL SOCIAL - PARTS SOCIALES"],
["p", 7, "Le capital social est fixé à la somme de DE FRANCS CFA ( FCFA), divisé en ( ) parts sociales de FRANCS CFA ( FCFA) chacune, numérotées de 1 à entièrement souscrites et libérées en numéraire, et attribuées aux associés en proportion de leurs apports respectifs, savoir :"],
["li", 7, "Monsieur, à concurrence de parts sociales, numérotées de 1 à, ci……………………………………………………....…………… P"],
["li", 7, "Monsieur, à concurrence de parts sociales, numérotées de à, ci………………………………………….…………… P"],
["p", 7, "TOTAL égal au nombre de parts composant le capital social :, ci................….........……………………………………………………………………… P"],
["art", 8, "ARTICLE HUIT : AUGMENTATION ET REDUCTION DU CAPITAL"],
["sub", 8, "I - AUGMENTATION DU CAPITAL"],
["p", 8, "Le capital social peut être augmenté en une ou plusieurs fois notamment par la création de parts nouvelles attribuées en représentation d’apports en nature ou en numéraire, capitalisation de tout ou partie des bénéfices, des réserves, des provisions ou dotations de toutes natures ou par l’augmentation de la valeur nominale des parts existantes."],
["p", 8, "Lorsque le capital social est augmenté par incorporation de bénéfices ou de réserves, la décision est prise par les associés représentant au moins la moitié (1/2) des parts sociales. Dans les autres cas d’augmentation, la décision devra être prise par les associés représentant au moins les trois-quarts (3/4) du capital social."],
["p", 8, "En cas d’augmentation de capital par souscription de parts sociales en numéraire, les fonds sont déposés en banque, dans tout autre établissement de crédit ou de microfinance dûment agrée, ou en l’Etude du Notaire conformément aux dispositions applicables lors de la création de la société."],
["p", 8, "Les parts sont obligatoirement libérées, lors de la souscription, de la moitié au moins de leur valeur nominale. La libération du surplus doit intervenir, en une ou plusieurs fois, dans le délai de deux (02) ans à compter du jour où l’augmentation de capital est devenue définitive."],
["p", 8, "Lorsque l’augmentation du capital est réalisée partiellement ou totalement par des apports en nature, un Commissaire aux apports doit être désigné par les associés conformément aux dispositions de l’Acte Uniforme sus-énoncé."],
["p", 8, "La décision collective portant augmentation de capital peut décider que celle-ci aura lieu par création de parts assorties d’une prime, dont elle fixera le montant ou l’affectation."],
["p", 8, "En cas d’augmentation de capital en numéraire, les associés ont, proportionnellement au nombre de parts possédées par chacun d’eux, un droit de préférence à la souscription des parts nouvelles, sauf renonciation par décision extraordinaire de la collectivité des associés."],
["p", 8, "Au cas où certains associés ne souscriraient pas la totalité des parts nouvelles auxquelles ils auraient droit, ou ne souscriraient qu’en partie, les parts nouvelles ainsi rendues disponibles seraient attribuées aux associés qui auraient déclaré vouloir souscrire un nombre de part supérieur à celui qu’ils auraient pu souscrire à titre préférentiel, et ce, proportionnellement à leur part dans le capital et dans la limite de leurs demandes."],
["p", 8, "Ce droit de préférence à titre irréductible et à titre réductible, auquel il pourra être renoncé en tout ou en partie par une décision extraordinaire de la collectivité des associés, sera exercé dans les formes, délais et conditions déterminés par la collectivité elle-même, ou à son défaut, par la gérance."],
["p", 8, "Les parts qui n’auraient pas été souscrites par les associés, ne pourront être attribuées qu’à des personnes agréées aux conditions fixées sous l’article dix ci-après pour les cessions de parts."],
["p", 8, "Ces parts, qui ne peuvent en aucun cas faire l’objet d’une souscription publique, doivent être entièrement libérées et réparties dès leur création."],
["sub", 8, "II - REDUCTION DU CAPITAL"],
["p", 8, "Le capital social peut également être réduit, en vertu d’une décision collective extraordinaire des associés pour quelque cause et de quelque manière que ce soit, notamment au moyen de remboursement aux associés ou de rachat des parts sociales, de réduction du montant ou du nombre des parts."],
["p", 8, "Toutefois, le capital social et le montant nominal des parts ne peuvent être réduits en dessous du minimum fixé par l’Acte Uniforme."],
["p", 8, "Cette réduction ne peut en aucun cas porter atteinte à l’égalité des associés."],
["art", 9, "ARTICLE NEUF : SOUSCRIPTION ET REPRESENTATION DES PARTS SOCIALES"],
["p", 9, "Les parts sociales ne peuvent jamais être représentées par des titres négociables, nominatifs ou au porteur."],
["p", 9, "Les droits de chaque associé dans la société résultent uniquement des présentes, des cessions de parts régulièrement consenties et de tous actes ultérieurs modificatifs des présentes."],
["p", 9, "Une copie, ou un extrait de ces actes et pièces certifiées conforme par la gérance, est délivrée à chaque associé sur sa demande et à ses frais."],
["art", 10, "ARTICLE DIX : DROITS ET OBLIGATIONS DES PARTS SOCIALES"],
["p", 10, "Chaque part sociale donne droit, proportionnellement au nombre de parts existantes, à une quotité dans la propriété et l’actif social, dans le partage des bénéfices et dans le boni de liquidation."],
["p", 10, "Elle donne également le droit de participer aux décisions collectives."],
["p", 10, "Les associés ne sont tenus à l’égard des tiers qu’à concurrence du montant de leur apport."],
["p", 10, "La propriété d’une part emporte de plein droit adhésion aux statuts et aux résolutions régulièrement prises par les associés."],
["p", 10, "Les droits et obligations attachés aux parts, les suivent, dans quelque main qu’elles passent."],
["p", 10, "Les représentants, ayants droit, conjoint et héritiers d’un associé ne peuvent, sous quelque prétexte que ce soit, requérir l’apposition des scellés sur les biens et valeurs de la société, ni en demander le partage ou la licitation."],
["art", 11, "ARTICLE ONZE : INDIVISIBILITE DES PARTS"],
["p", 11, "Les parts sociales sont indivisibles à l’égard de la société qui ne reconnaît qu’un seul propriétaire pour chaque part."],
["p", 11, "A cet égard, les indivisions successorales sont considérées comme un seul associé quel que soit le nombre de parts possédées par cette indivision."],
["p", 11, "Les copropriétaires indivis sont tenus de désigner l’un d’entre eux pour les représenter auprès de la société; à défaut d’entente, il appartient à l’indivisaire le plus diligent de faire désigner par voie de justice un mandataire chargé de le représenter."],
["p", 11, "Dans le cas où la majorité par tête est requise pour la validité des décisions collectives, l’indivision n’est comptée que pour une seule tête."],
["art", 12, "ARTICLE DOUZE : CESSION ET TRANSMISSION DES PARTS SOCIALES"],
["sub", 12, "I - CESSIONS"],
["p", 12, "Toute cession de parts sociales doit être constatée par écrit."],
["p", 12, "La cession n’est rendue opposable à la société qu’après l’accomplissement de l’une des formalités suivantes :"],
["li", 12, "Signification de la cession à la société par exploit d’huissier ou notification par tout moyen permettant d’établir sa réception effective par le destinataire."],
["li", 12, "Acceptation de la cession par la société dans un acte authentique."],
["li", 12, "Dépôt d’un original de l’acte de cession au siège social contre remise par le gérant d’une attestation de ce dépôt."],
["p", 12, "La cession n’est opposable aux tiers qu’après l’accomplissement de l’une des formalités ci-dessus, et modification des statuts et publicité au Registre du Commerce et du Crédit Mobilier."],
["p", 12, "Les parts sociales peuvent être cédées ou transmises librement par les associés."],
["sub", 12, "II - TRANSMISSION PAR DECES"],
["p", 12, "En cas de décès d’un associé, la société continue entre les associés survivants, les héritiers et ayants-droit de l’associé décédé et éventuellement son conjoint survivant, lesquels héritiers, ayants-droit et conjoint survivant ne sont pas soumis à l’agrément des associés survivants."],
["p", 12, "Pour l’exercice de leurs droits d’associés, les héritiers ou ayants-droit doivent justifier de leur identité personnelle et de leurs qualités héréditaires, la gérance pouvant exiger la production d’expéditions ou d’extraits de tous actes notariés établissant cette qualité."],
["p", 12, "Ils doivent également justifier de la désignation du mandataire commun chargé de les représenter pendant la durée de l’indivision dans les conditions prévues à l’article 12 ci-dessus des présents statuts."],
["sub", 12, "III - NANTISSEMENT DES PARTS SOCIALES"],
["p", 12, "Si la société donne son consentement à un projet de nantissement de parts sociales soit par notification de sa décision à l’intéressé, soit par défaut de réponse dans un délai de trois (3) mois à compter de sa demande, ce consentement emportera agrément du cessionnaire en cas de réalisation forcée des parts sociales régulièrement nanties, à moins que la société ne préfère, après la cession, racheter sans délai lesdites parts en vue de réduire son capital."],
["p", 12, "Pour que le nantissement des parts sociales soit opposable aux tiers, il doit être constaté par un acte notarié ou par acte sous seing privé signifié à la société, et publié au Registre du Commerce et du Crédit Mobilier."],
["art", 13, "ARTICLE TREIZE : INTERDICTION, FAILLITE OU DECONFITURE"],
["p", 13, "L’incapacité, l’interdiction, la faillite ou la déconfiture de l’un des associés, ainsi que le règlement judiciaire ou la liquidation de ses biens n’entraîne pas la dissolution de la Société, mais si l’un de ces événements se produit en la personne d’un gérant, il entraînera la cessation de ses fonctions de gérant."],
["part", 14, "TITRE TROIS : GERANCE"],
["art", 14, "ARTICLE QUATORZE : NOMINATION DU GERANT"],
["p", 14, "La Société est gérée par une ou plusieurs personnes physiques choisies parmi les associés ou en dehors d’eux. Elles sont nommées pour une durée indéterminée. La nomination des gérants au cours de la vie sociale est décidée à la majorité de plus de la moitié des parts."],
["p", 14, "Dès à présent Monsieur est nommé gérant pour une durée indéterminée. Lequel déclare accepter ces fonctions et n’être frappé d’aucune incapacité d’exercer lesdites fonctions."],
["p", 14, "Le ou les gérants peuvent démissionner de leur mandat, mais seulement en prévenant chacun des associés au moins trois (3) mois à l’avance, par lettre recommandée avec demande d’avis de réception ou lettre au porteur contre récépissé."],
["p", 14, "Le ou les gérants sont révocables par décision des associés représentant plus de la moitié des parts sociales."],
["p", 14, "La rémunération du gérant est fixée par la décision qui le nomme."],
["art", 15, "ARTICLE QUINZE : RESPONSABILITE ET REMUNERATION DU GERANT"],
["p", 15, "Chaque gérant est responsable, conformément aux règles du droit commun, individuellement ou solidairement suivant les cas, envers la société et envers les tiers soit des infractions aux dispositions de la loi et des règlements, soit des violations des présents statuts, soit des fautes commises par eux dans leur gestion."],
["p", 15, "Il ne contracte, en raison de ses fonctions, aucune obligation personnelle relativement aux engagements de la société, et n’est responsable que de l’exécution de son mandat."],
["p", 15, "Si plusieurs gérants ont coopéré aux mêmes faits, le Tribunal chargé des affaires commerciales détermine la part contributive de chacun dans la réparation du dommage."],
["p", 15, "Les fonctions du ou des gérants sont gratuites ou rémunérées dans les conditions fixées dans les statuts, ou dans une décision collective des associés."],
["p", 15, "En rémunération de ses fonctions et en compensation de la responsabilité attachée à la gestion, chaque gérant peut avoir droit à un traitement fixe ou proportionnel dont le montant et les modalités de paiement seront déterminées par décision collective ordinaire des associés; il a droit au remboursement de ses frais de représentation et de déplacement; il peut en outre avoir droit à titre de complément de rémunération à un pourcentage dans les bénéfices."],
["part", 16, "TITRE QUATRE : CONTROLE DE LA SOCIETE"],
["p", 15, "Si la société, à la clôture de l’exercice social, remplit deux des conditions suivantes :"],
["li", 15, "Total du bilan supérieur à CENT VINGT CINQ MILLIONS (125 000 000) DE FRANCS CFA;"],
["li", 15, "Un chiffre d’affaires annuel supérieur à DEUX CENT CINQUANTE MILLIONS (250 000 000) DE FRANCS CFA;"],
["li", 15, "Un effectif permanent supérieur à CINQUANTE (50) personnes;"],
["p", 15, "Elle sera tenue de désigner au moins un commissaire aux comptes."],
["p", 15, "Dans les autres cas, la nomination d’un Commissaire aux comptes est facultative."],
["p", 15, "Elle peut toutefois être demandée en justice par un ou plusieurs associés détenant au moins, le dixième du capital social."],
["art", 16, "ARTICLE SEIZE : NOMINATION DU COMMISSAIRE AUX COMPTES"],
["p", 16, "La nomination des Commissaires aura lieu par décision des associés pour une durée de trois ans."],
["p", 16, "Ses fonctions expireront avec l’Assemblée Générale qui statuera sur les comptes du dernier de ces exercices, sauf renouvellement."],
["art", 17, "ARTICLE DIX-SEPT : INCOMPATIBILITES - CONDITIONS D’EXERCICE"],
["p", 17, "Les incompatibilités et les conditions d’exercice sont fixées selon les dispositions des articles 378 et suivants de l’Acte Uniforme."],
["part", 18, "TITRE CINQ : CONVENTIONS ENTRE UN GERANT OU UN ASSOCIE ET LA SOCIETE"],
["art", 18, "ARTICLE DIX-HUIT : CONVENTIONS SOUMISES A PROCEDURE SPECIALE"],
["p", 18, "La gérance ou le Commissaire aux Comptes, s’il en existe un, présente à l’assemblée statuant sur les comptes d’un exercice ou joint aux documents communiqués aux associés en cas de consultation écrite, un rapport sur :"],
["li", 18, "les conventions intervenues directement ou par personne interposée entre la société et l’un de ses gérants ou associés,"],
["li", 18, "pour les conventions intervenues entre une entreprise individuelle dont le propriétaire est simultanément gérant ou associé de la société à responsabilité limitée,"],
["li", 18, "pour les conventions intervenues avec une société dont un associé indéfiniment responsable, gérant, administrateur, directeur général ou secrétaire général est simultanément gérant ou associé de la société à responsabilité limitée."],
["p", 18, "Le gérant avise le Commissaire aux Comptes de la conclusion desdites conventions dans le mois de leur signature."],
["p", 18, "Le gérant présente à l’Assemblée ou joint aux documents communiqués aux associés, en cas de consultation écrite, un rapport sur les conventions contenant les mentions suivantes :"],
["li", 18, "l’énumération des conventions soumises à l’approbation de l’Assemblée des associés;"],
["li", 18, "l’identification des parties à la convention et le nom des gérants ou associés intéressés;"],
["li", 18, "la nature et l’objet desdites conventions;"],
["li", 18, "les modalités essentielles de ces conventions, notamment l’indication des prix ou tarifs pratiqués, des ristournes et commissions consenties, des délais de paiement accordés, des intérêts stipulés, des sûretés conférées et, le cas échéant, toutes autres indications permettant aux associés d’apprécier l’intérêt qui s’attachait à la conclusion des conventions analysées;"],
["li", 18, "l’importance des fournitures livrées ou des prestations de services fournies, ainsi que le montant des sommes versées ou reçues au cours de l’exercice en exécution des conventions conclues au cours d’exercices antérieurs et dont l’exécution a été poursuivie au cours du dernier exercice."],
["p", 18, "L’Assemblée statue sur ce rapport. Le gérant ou l’associé intéressé ne peut pas prendre part au vote et ses parts ne sont pas prises en compte pour le calcul de la majorité."],
["p", 18, "Les conventions non approuvées produisent néanmoins leurs effets, à charge par le gérant, ou l’associé contractant de supporter individuellement ou solidairement, selon le cas, les conséquences du contrat préjudiciable à la société."],
["p", 18, "Ces dispositions toutefois ne sont pas applicables aux conventions portant sur les opérations courantes et conclues à des conditions normales."],
["p", 18, "Lorsque la société ne comprend qu’un seul associé et que cette convention est conclue avec lui, il en est seulement fait mention sur le registre des délibérations."],
["art", 19, "ARTICLE DIX-NEUF : CONVENTIONS INTERDITES"],
["p", 19, "A peine de nullité du contrat, il est interdit au gérant ou aux associés de contracter, sous quelque forme que ce soit, des emprunts auprès de la société, de se faire consentir par elle un découvert, en compte courant ou autrement, ainsi que de faire cautionner ou avaliser par elle leurs engagements envers les tiers."],
["p", 19, "Cette interdiction s’applique également au conjoint, ascendant ou descendant du gérant ou des associés ainsi qu’à toute personne interposée."],
["part", 20, "TITRE SIX : DECISIONS COLLECTIVES - DROIT DE COMMUNICATION PERMANENT D’INFORMATION ET DE CONTROLE DES ASSOCIES"],
["art", 20, "ARTICLE VINGT : DECISIONS COLLECTIVES"],
["p", 20, "La volonté des associés s’exprime par des décisions collectives prises en Assemblée."],
["sub", 20, "I - DECISIONS COLLECTIVES ORDINAIRES"],
["p", 20, "Sont qualifiées d’ordinaires, les décisions des associés ayant pour but de statuer sur les états financiers de synthèse, d’autoriser la gérance à effectuer les opérations subordonnées dans les Statuts à l’accord préalable des associés, de nommer et de remplacer les gérants et, le cas échéant, le Commissaire aux Comptes, d’approuver les conventions intervenues entre la Société et les gérants et associés et plus généralement de statuer sur toutes les questions qui n’entraînent pas modification des Statuts."],
["p", 20, "Ces décisions sont valablement adoptées par un ou plusieurs associés représentant plus de la moitié des parts sociales. Si cette majorité n’est pas obtenue, les associés sont, selon le cas, convoqués ou consultés une seconde fois, et les décisions sont prises à la majorité des votes émis, quel que soit le nombre de votants."],
["p", 20, "Toutefois, la révocation des gérants doit toujours être décidée à la majorité absolue."],
["sub", 20, "II - DECISIONS COLLECTIVES EXTRAORDINAIRES"],
["p", 20, "La volonté des associés s’exprime par des décisions collectives qui obligent tous les associés, qu’ils aient, ou non pris part."],
["p", 20, "Les décisions collectives sont prises, au choix de la gérance, soit en assemblée, soit par consultation écrite, sauf dans les cas où la loi impose la tenue d’une Assemblée."],
["p", 20, "L’Assemblée est convoquée par les gérants individuellement ou collectivement ou, à défaut par le Commissaire aux comptes, s’il en existe un, ou, encore par mandataire désigné en justice à la demande de tout associé."],
["p", 20, "Pendant la liquidation, les assemblées sont convoquées par le ou les liquidateurs."],
["p", 20, "Les assemblées sont réunies au lieu indiqué dans la convocation. La convocation est faite par lettre recommandée avec demande d’avis de réception ou par lettre au porteur contre récépissé adressé à chacun des associés, quinze (15) jours au moins avant la date de la réunion. Celle-ci indique l’ordre du jour."],
["p", 20, "L’Assemblée est présidée par l’un des gérants. Si aucun des gérants n’est associé, elle est présidée par l’associé présent ou acceptant qui possède ou représente le plus grand nombre de parts. Si deux associés qui possèdent ou représente le même nombre de parts sont acceptants, la présidence de l’Assemblée est assurée par le plus âgé."],
["p", 20, "La délibération est constaté par un procès-verbal qui indique la date et le lieu de la réunion, les nom et prénoms des associés présents sur nombre de parts sociales détenues par chacun, les documents et rapports soumis à l’Assemblée, un résumé des débats, le texte des résolutions mises aux voix et le résultat des votes. Les procès-verbaux sont signés par chacun des associés présents."],
["p", 20, "En cas de consultation écrite, le texte des résolutions proposées ainsi que les documents nécessaires à l’information des associés sont adressés à chacun d’eux par lettre recommandée avec demande d’avis de réception ou par lettre au porteur contre récépissé. Les associés disposent d’un délai minimal de quinze (15) jours, à compter de la date de réception des projets de résolutions pour émettre leur vote par écrit."],
["p", 20, "La réponse est faite par lettre recommandée avec demande d’avis de réception ou par lettre contre récépissé; tout associé n’ayant pas répondu dans le délai ci-dessus est considéré comme s’étant abstenu."],
["p", 20, "La consultation est mentionnée dans un procès-verbal, auquel est annexée la réponse de chaque associé."],
["p", 20, "Chaque associé a le droit de participer aux décisions et dispose d’un nombre de voix égal à celui des parts sociales qu’il possède."],
["p", 20, "Un associé peut se faire représenter par son conjoint à moins que la Société ne comprenne que les deux époux. Sauf si les associés sont au nombre de deux, un associé peut se faire représenter par un autre associé."],
["p", 20, "Tout associé peut se faire représenter par la personne de son choix."],
["sub", 20, "III - ASSEMBLEE GENERALE ANNUELLE"],
["p", 20, "Des décisions collectives de toute nature peuvent être prises à toute époque, mais les associés doivent obligatoirement être consultés une (1) fois par an, dans les six (6) mois qui suivent la clôture de chaque exercice social pour approuver les états financiers de synthèse de l’exercice écoulé."],
["p", 20, "Les gérants peuvent demander une prorogation de ce délai au Président de la juridiction compétente statuant sur requête."],
["p", 20, "Ces décisions collectives ne peuvent être prises par consultation écrite des associés."],
["sub", 20, "IV - MODE DE CONSULTATION"],
["sub", 20, "1°) Consultations écrites"],
["p", 20, "En cas de consultation par correspondance, la gérance ou le Commissaire aux comptes, s’il existe un, envoie à chaque associé à son dernier domicile connu, par lettre au porteur contre récépissé ou par lettre recommandée avec avis de réception, télécopie ou courrier électronique, le texte des résolutions proposées accompagné d’un rapport explicatif, et, en outre, s’il s’agit d’approuver les états financiers de synthèse de l’exercice écoulé d’un exemplaire du bilan et du compte de résultats, certifiés conformes."],
["p", 20, "Les convocations par télécopie et courrier électronique ne sont valables que si l’associé a préalablement donné son accord écrit et communiqué son numéro de télécopie ou son adresse électronique, selon le cas. Il peut à tout moment demander expressément à la société par lettre recommandée avec demande d’avis de réception que le moyen de communication susmentionné soit remplacé à l’avenir par un envoi postal."],
["p", 20, "Les associés doivent, dans le délai de quinze (15) jours à compter de la date d’envoi de ladite lettre recommandée, adresser à la gérance, également par lettre recommandée avec accusé de réception, télécopie et courrier électronique notification de leur acceptation ou de leur refus; le vote est formulé par les mots « OUI » ou « NON » pour chacune des résolutions."],
["p", 20, "Tout associé n’ayant pas répondu dans le délai imparti sera considéré comme s’étant abstenu."],
["p", 20, "Il ne sera fait aucun état des votes qui seraient reçus après l’expiration de ce délai pendant lequel les associés auront le droit d’exiger tous renseignements complémentaires sur les résolutions à eux soumises."],
["sub", 20, "2°) Consultations en Assemblée Générale"],
["p", 20, "Les décisions collectives ordinaires ou extraordinaires résultent d’une Assemblée Générale à défaut d’un acte rapportant l’accord unanime des associés."],
["p", 20, "Lorsque la consultation a lieu en Assemblée Générale, la convocation en est faite par la gérance ou le Commissaire aux comptes, s’il en existe un, ou par des associés représentant au moins la moitié (1/2) du capital social, quinze (15) jours au moins à l’avance par lettre au porteur contre récépissé ou par lettre recommandée avec avis de réception, télécopie ou courrier électronique adressée à chacun des associés à son dernier domicile connu, contenant indication des dates, heure et lieu, ainsi que l’ordre du jour de la réunion."],
["p", 20, "L’Assemblée est présidée par le gérant, ou l’un d’eux s’ils sont plusieurs, ou à défaut par l’un des membres de l’Assemblée désigné par elle."],
["p", 20, "Si aucun des gérants n’est associé, l’Assemblée est présidée par l’associé présent et acceptant qui possède le plus grand nombre de parts sociales et, en cas d’égalité, par le plus âgé."],
["p", 20, "Les fonctions de scrutateurs sont remplies par les deux (2) associés représentant tant par eux-mêmes que comme mandataire, le plus grand nombre de parts sociales, et, sur leur refus, par ceux qui viennent ensuite, jusqu’à acceptation."],
["p", 20, "Le bureau ainsi constitué désigne, s’il y a lieu, un secrétaire qui peut être choisi en dehors des associés."],
["p", 20, "Toutefois si la société ne compte que trois (3) associés au plus, il ne sera pas constitué de bureau."],
["p", 20, "Une feuille de présence indiquant les nom, prénoms et domicile des associés ou de leur représentant ou mandataire, ainsi que le nombre de parts sociales détenues par chaque associé, est émargée par les membres de l’Assemblée, certifiée exacte par le bureau et doit ensuite être déposée au siège social."],
["p", 20, "Seules sont mises en délibération les questions figurant à l’ordre du jour."],
["p", 20, "La gérance est tenue de soumettre au vote des associés, le texte des résolutions portées à l’ordre du jour et le texte des résolutions qui lui auront été proposées par un ou plusieurs associés, quelle que soit la portion du capital qu’ils représentent au plus tard huit (8) jours avant l’envoi des lettres de convocations si la consultation a lieu par voie d’Assemblée, ou en demandant le vote écrit dans le cas de consultation par correspondance."],
["p", 20, "En outre, les décisions collectives peuvent être prises en Assemblée Générale convoquée à la demande d’un ou plusieurs associés, représentant plus de la moitié (1/2) du capital social ou s’ils représentent au moins le quart (1/4) des associés détenant le quart (1/4) des parts sociales, à défaut par la gérance d’avoir convoqué les associés huit (8) jours après une mise en demeure à elle adressée par lettre recommandée avec avis de réception."],
["p", 20, "En pareil cas, la convocation ou la demande de vote par correspondance émane du ou de l’un des associés requérants qui est soumis aux mêmes formalités que la gérance elle-même à laquelle il se substitue à cet effet."],
["p", 20, "En outre, tout associé peut demander en justice la désignation d’un mandataire chargé de convoquer l’Assemblée ou de fixer son ordre du jour."],
["p", 20, "Tout associé peut participer à toutes les décisions collectives, quelle que soit leur nature et quel que soit le nombre de ses parts, avec un nombre de voix égal au nombre de parts qu’il possède sans limitation."],
["p", 20, "Sauf s’ils sont au nombre de deux (2), tout associé peut se faire représenter par un autre associé muni de son pouvoir à une Assemblée Générale, mais le vote par correspondance est strictement personnel et ne peut être délégué."],
["p", 20, "Le mandat donné à un autre associé ou à un autre tiers ne vaut que pour une seule Assemblée ou pour plusieurs Assemblées successives convoquées avec le même ordre du jour."],
["p", 20, "Les représentants légaux d’associés juridiquement incapables peuvent participer à tous les votes, sans être par eux-mêmes associés."],
["art", 21, "ARTICLE VINGT ET UN : ASSEMBLEE STATUANT SUR LES COMPTES SOCIAUX"],
["sub", 21, "I - REUNION DE L’ASSEMBLEE"],
["p", 21, "Dans le délai de six mois qui suit la clôture de l’exercice, le rapport sur les opérations de l’exercice, l’inventaire, le compte de résultat et l’annexe établis par le gérant sont soumis à l’approbation de chaque associé."],
["sub", 21, "II - DROIT DE COMMUNICATION ET D’INFORMATION DES ASSOCIES"],
["p", 21, "Les états financiers de synthèse ainsi que le rapport de gestion établi par la gérance, sont tenus au siège social à la disposition des Commissaires aux comptes, s’il en existe, un mois au moins avant la convocation de l’Assemblée."],
["p", 21, "Les états financiers de synthèse, le rapport de gestion ainsi que le texte des résolutions proposées, et, le cas échéant, les rapports du Commissaire aux Comptes annuels, sont communiqués ou tenus à la disposition de l’associé unique quinze jours au moins avant la date de l’Assemblée."],
["p", 21, "A compter de la communication des documents prévus à l’alinéa précédent, tout associé a la faculté de poser par écrit des questions auxquelles le gérant sera tenu de répondre au cours de l’Assemblée."],
["art", 22, "ARTICLE VINGT DEUX : DECISIONS PRISES PAR CONSULTATION ECRITE DES ASSOCIES"],
["sub", 22, "I - MODALITE DE LA CONSULTATION"],
["p", 22, "En cas de consultation écrite, le texte des résolutions proposées ainsi que les documents nécessaires à l’information de chaque associé sont adressés à celui-ci par lettre au porteur contre récépissé ou par lettre recommandée avec demande d’avis de réception télécopie ou courrier électronique."],
["p", 22, "Chaque associé dispose d’un délai de vingt jours à compter de la date de réception des projets de résolution, pour émettre son vote par écrit."],
["p", 22, "Tout associé qui n’aura pas répondu dans ce délai sera considéré comme s’étant abstenu. Pour chaque résolution, le vote est exprimé par oui ou par non."],
["sub", 22, "II - MENTION SPECIALE DANS LES PROCES-VERBAUX"],
["p", 22, "En cas de consultation écrite, les procès-verbaux sont tenus dans les mêmes conditions que celles prévues par les présents Statuts relatives aux décisions prises en Assemblées."],
["p", 22, "Toutefois, il y est mentionné que la consultation a été effectuée par écrit."],
["p", 22, "La réponse de chaque associé est annexée à ces procès-verbaux."],
["art", 23, "ARTICLE VINGT TROIS : DROIT DE COMMUNICATION PERMANENT, D’INFORMATION ET DE CONTROLE DES ASSOCIES"],
["sub", 23, "I - DROIT DE COMMUNICATION PERMANENT"],
["p", 23, "Tout associé a le droit, à toute époque, d’obtenir, au siège social, la délivrance d’une copie certifiée des statuts en vigueur au jour de la demande."],
["p", 23, "La société doit annexer à ce document la liste des gérants et, le cas échéant, des Commissaires aux comptes en exercice."],
["p", 23, "L’associé a également le droit, à toute époque de prendre par lui-même et au siège social, connaissance des documents suivants : états financiers de synthèse, inventaires, rapports soumis aux Assemblées concernant les trois derniers exercices."],
["p", 23, "Sauf en ce qui concerne l’inventaire, le droit de prendre connaissance emporte celui de prendre copie."],
["sub", 23, "II - PROCEDURE D’ALERTE"],
["p", 23, "Tout associé non gérant peut, deux fois par an, poser par écrit des questions au gérant sur tout fait de nature à compromettre la continuité de l’exploitation."],
["p", 23, "La réponse du gérant est communiquée au Commissaire aux comptes."],
["part", 24, "TITRE SEPT : EXERCICE SOCIAL - COMPTES SOCIAUX - INFORMATION COMPTABLE ET FINANCIERE - AFFECTATION ET REPARTITION DES BENEFICES"],
["art", 24, "ARTICLE VINGT QUATRE : EXERCICE SOCIAL"],
["p", 24, "L’exercice social commence le premier janvier et se termine le trente et un décembre de chaque année."],
["p", 24, "Par exception, le premier exercice social comprendra le temps à courir depuis le jour de la constitution définitive de la société jusqu’au trente et un décembre qui suit."],
["art", 25, "ARTICLE VINGT CINQ : COMPTES SOCIAUX"],
["sub", 25, "I - ETABLISSEMENT DES COMPTES SOCIAUX"],
["p", 25, "A la clôture de chaque exercice, la gérance dresse l’inventaire des divers éléments de l’actif et du passif existant à cette date."],
["p", 25, "Elle dresse également les états financiers de synthèse."],
["p", 25, "Le montant des engagements cautionnés, avalisés ou garantis est mentionné à la suite du bilan, ainsi qu’un état des sûretés consenties par la société."],
["p", 25, "Elle établit un rapport de gestion sur la situation de la société et son activité au cours de l’exercice écoulé, les résultats de cette activité, les progrès réalisés et les difficultés rencontrées, l’évolution prévisible de cette situation et la situation de trésorerie et le plan de financement."],
["sub", 25, "II - FORMES ET METHODES D’EVALUATION DES COMPTES SOCIAUX"],
["p", 25, "Les états financiers de synthèse sont établis après chaque exercice selon les mêmes formes et les mêmes méthodes d’évaluation que les années précédentes, sauf si un changement exceptionnel est intervenu dans la situation de la société."],
["p", 25, "Dans ce dernier cas, les modifications doivent être décrites et justifiées dans le rapport de gestion et le cas échéant, dans le rapport des Commissaires aux comptes."],
["art", 26, "ARTICLE VINGT SIX : AFFECTATION ET REPARTITION DES BENEFICES"],
["sub", 26, "I - DEFINITION"],
["sub", 26, "1 - Réserve légale"],
["p", 26, "A peine de nullité de toute délibération contraire, il est fait sur le bénéfice de l’exercice diminué le cas échéant, des pertes antérieures, un prélèvement de un dixième au moins affecté à la formation d’un fonds de réserve dit \"réserve légale\"."],
["p", 26, "Ce prélèvement cesse d’être obligatoire, lorsque la réserve atteint le cinquième du capital social."],
["sub", 26, "2 - Bénéfice distribuable"],
["p", 26, "Le bénéfice distribuable est déterminé par le résultat de l’exercice augmenté du report bénéficiaire et diminué des pertes antérieures ainsi que des sommes portées en réserve en application de la loi et des décisions collectives."],
["p", 26, "En outre, l’Assemblée Générale peut décider la mise en distribution de sommes prélevées sur les réserves dont elle a la disposition; en ce cas, la décision indique expressément les postes de réserve sur lesquels les prélèvements sont effectués."],
["p", 26, "Hors le cas de réduction du capital, aucune distribution ne peut être faite aux associés lorsque les capitaux propres sont ou deviendraient, à la suite de celle-ci, inférieurs au montant du capital augmenté des réserves que la loi ou les statuts ne permettent pas de distribuer."],
["sub", 26, "3 - Report à nouveau"],
["p", 26, "L’Assemblée peut décider l’inscription, au compte report à nouveau, de tout ou partie des bénéfices distribuables. Elle fixe l’affectation ou l’emploi des bénéfices ainsi inscrits à ces comptes."],
["p", 26, "Ils peuvent être affectés notamment au financement des investissements de la société."],
["sub", 26, "4 - Sommes distribuables"],
["p", 26, "Le total du bénéfice et des réserves, diminué le cas échéant des sommes inscrites au compte report à nouveau, dont l’Assemblée à la disposition constitue les sommes distribuables."],
["sub", 26, "II - REPARTITION DES BENEFICES DIVIDENDES"],
["sub", 26, "1 - Affectation des bénéfices"],
["p", 26, "Après approbation des comptes et constatation de l’existence des sommes distribuables, l’Assemblée Générale détermine les dotations à des réserves facultatives, la part attribuée aux associés sous forme de dividendes, le montant du report à nouveau."],
["p", 26, "Tout dividende distribué en violation des règles ci-dessus énoncées est un dividende fictif."],
["sub", 26, "2 - Paiement des dividendes"],
["p", 26, "Les modalités de mise en paiement des dividendes, votés par l’Assemblée Générale, sont fixées par elle ou, à défaut, par la gérance."],
["p", 26, "Toutefois, la mise en paiement des dividendes doit avoir lieu dans un délai maximum de neuf mois après la clôture de l’exercice; la prolongation de ce délai peut être accordée par voie de justice."],
["art", 27, "ARTICLE VINGT SEPT : COMPTES COURANTS D’ASSOCIES"],
["p", 27, "Chaque associé a la possibilité, avec le consentement de la gérance, de verser dans la caisse sociale les fonds jugés utiles aux besoins de la société."],
["p", 27, "Les conditions de fonctionnement de ces comptes, la fixation des intérêts, les délais pour retirer les sommes sont arrêtés dans chaque cas par accord entre la gérance et les intéressés en appliquant les dispositions de l’article 19 des présents statuts."],
["part", 28, "TITRE HUIT : TRANSFORMATION - DISSOLUTION - LIQUIDATION"],
["art", 28, "ARTICLE VINGT HUIT : TRANSFORMATION"],
["p", 28, "La société peut se transformer en société d’une autre forme si, au moment où la transformation est envisagée, elle a des capitaux propres d’un montant au moins égal à son capital social."],
["p", 28, "La transformation ne peut être faite qu’au vu d’un rapport d’un commissaire aux comptes ou s’il n’existe pas de commissaires aux comptes celui choisi par le ou les gérants."],
["p", 28, "Lorsqu’une société qui n’a pas de commissaires aux comptes se transforme en société par actions, un ou plusieurs commissaires à la transformation sont désignés, sauf d’accord unanime des associés, par décision de la juridiction compétente à la demande des dirigeants sociaux ou de l’un d’eux."],
["p", 28, "La transformation en société en nom collectif ou en société par actions simplifiée, nécessite l’unanimité des associés."],
["art", 29, "ARTICLE VINGT NEUF : DISSOLUTION"],
["sub", 29, "1 - Dissolution à l’arrivée du terme à défaut de prorogation"],
["p", 29, "La société est dissoute à la date d’expiration de sa durée. Un an au moins avant cette date, la gérance convoque l’Assemblée Générale Extraordinaire pour décider ou non la prorogation de la société."],
["p", 29, "La décision des associés sera dans tous les cas rendue publique."],
["p", 29, "A défaut de procéder à la convocation de cette Assemblée, le gérant ou tout associé, peut demander au Président du Tribunal de commerce du siège social, la désignation d’un mandataire de justice chargé de convoquer cette Assemblée."],
["sub", 29, "2 - Dissolution anticipée"],
["sub", 29, "a) Réunion de toutes les parts sociales en une seule main"],
["p", 29, "La réunion de toutes les parts en une seule main n’entraîne pas la dissolution de plein droit de la société."],
["sub", 29, "b) Décision des associés"],
["p", 29, "La dissolution anticipée de la société peut être décidée à tout moment par les associés représentant plus des trois quarts du capital social."],
["sub", 29, "c) Réduction des capitaux propres à un montant inférieur à la moitié du capital social"],
["p", 29, "Si les capitaux propres deviennent inférieurs à la moitié du capital social, le gérant ou le Commissaire aux comptes est tenu dans les quatre mois qui suivent l’approbation des comptes ayant fait apparaître cette perte, de consulter les associés à l’effet de décider s’il y a lieu à la dissolution anticipée de la société."],
["p", 29, "Si la dissolution n’est pas prononcée, le capital doit être réduit d’un montant égal à la perte constatée au plus tard lors de la clôture du second exercice suivant celui au cours duquel les pertes portant atteinte au capital ont été constatées."],
["p", 29, "Il n’y a pas lieu à dissolution ou à réduction de capital si, dans le délai ci-dessus précisé, les capitaux propres viennent à être reconstitués pour une valeur supérieure à la moitié du capital social."],
["p", 29, "A défaut de réunion des associés, tout intéressé peut demander en justice la dissolution de la société. Il en est de même si les dispositions de l’alinéa 2 ci-dessus n’ont pas été appliquées. Si la régularisation a eu lieu avant que le Tribunal ne statue sur le fond, la dissolution ne sera pas prononcée."],
["sub", 29, "d) Réduction du capital à un montant inférieur au minimum légal"],
["p", 29, "En cas d’inobservation des dispositions relatives au maintien du capital à un montant au moins égal au minimum légal, tout intéressé peut demander en justice la dissolution de la société. Cette dissolution ne peut être prononcée si au jour où le Tribunal statue sur le fond, la régularisation a eu lieu."],
["art", 30, "ARTICLE TRENTE : LIQUIDATION"],
["p", 30, "A l’expiration de la société ou en cas de dissolution anticipée pour telle cause que ce soit, les associés, par une décision collective extraordinaire, règlent le mode de liquidation et nomment un ou plusieurs liquidateurs dont ils déterminent les fonctions à la majorité en capital des associés. Le ou les gérants alors en exercice, un ou plusieurs associés peuvent être nommés liquidateurs."],
["p", 30, "Le liquidateur peut être choisi parmi les associés, les tiers ou par décision de justice à la demande de tout intéressé. Il peut être une personne morale."],
["p", 30, "Cette nomination met fin aux pouvoirs de la gérance proprement dite qui doit remettre ses comptes à la liquidation, avec toutes pièces justificatives qu’il y a lieu en vue de leur approbation par une décision collective ordinaire ultérieure des associés."],
["p", 30, "La collectivité des associés conserve pendant la liquidation et seulement pour les besoins de cette liquidation, les mêmes attributions qu’au cours de la vie sociale."],
["p", 30, "Elle a notamment le pouvoir par décision ordinaire de révoquer le ou les liquidateurs en exercice, et d’en nommer de nouveaux, d’approuver leurs comptes et de leur en donner quitus, et par décision extraordinaire de modifier les statuts dans la mesure où ces modifications sont nécessaires pour les besoins de la liquidation."],
["p", 30, "Toutefois, si les associés sont réunis en Assemblée Générale, cette Assemblée est présidée par le liquidateur unique ou par le plus âgé des liquidateurs s’ils sont plusieurs."],
["p", 30, "Le liquidateur unique ou les liquidateurs s’ils sont plusieurs, agissant ensemble ou séparément, ont les pouvoirs les plus étendus à l’effet de réaliser l’actif social en bloc ou en détail même à l’amiable et d’acquitter le passif."],
["p", 30, "Ils peuvent, en outre, en vertu d’une décision collective extraordinaire des associés, faire l’apport de tout ou partie des biens sociaux à une autre Société à Responsabilité Limitée ou à une Société par Actions, et accepter en représentation de cet apport la remise de parts spéciales ou d’actions entièrement libérées. Ledit apport pourra notamment être effectué par voie de fusion ou de scission."],
["p", 30, "Après l’extinction du passif et des charges sociales, le produit net de la liquidation est employé à rembourser aux associés le capital social non amorti, et le surplus est réparti entre les associés gérants et non gérants proportionnellement au nombre de parts sociales possédées par chacun d’eux."],
["p", 30, "Dans les mêmes conditions de majorité pourra être réalisée la cession, à une autre société ou à toute autre personne, de l’ensemble des biens, droits et obligations tant actifs que passifs de la société dissoute."],
["p", 30, "Après l’acquit du passif et des charges sociales, le produit net de la liquidation est employé tout d’abord à rembourser le montant des parts sociales si ce remboursement n’a pas encore été opéré."],
["p", 30, "Le surplus est réparti entre tous les associés, gérants ou non-gérants, au prorata du nombre de parts leur appartenant."],
["p", 30, "Les pertes, s’il en existe, seront supportées dans les mêmes proportions sans qu’aucun des associés ne puisse en être tenu au-delà du montant de ses parts."],
["p", 30, "Pendant la société et après sa dissolution jusqu’à complète liquidation, les biens et valeurs sociaux resteront toujours la propriété de l’être moral et collectif et ne devront jamais être considérés comme appartenant indivisément aux associés ou à leurs héritiers ou représentants."],
["part", 31, "TITRE NEUF : CONTESTATIONS - ACTES ACCOMPLIS POUR LE COMPTE DE LA SOCIETE EN FORMATION - DISPOSITIONS DIVERSES"],
["art", 31, "ARTICLE TRENTE ET UN : CONTESTATIONS"],
["p", 31, "Toutes contestations qui peuvent s’élever pendant le cours de la société ou de sa liquidation, soit entre associés et la société, soit entre associés eux-mêmes, concernant les affaires sociales, l’interprétation ou l’exécution des présents statuts, sont soumises à la juridiction des tribunaux compétents."],
["art", 32, "ARTICLE TRENTE DEUX : PUBLICITE"],
["p", 32, "A cet effet, tous pouvoirs sont donnés aux porteurs d’originaux ou de copies des présentes pour effectuer les différentes formalités prescrites par la loi."],
["art", 33, "ARTICLE TRENTE TROIS : FRAIS"],
["p", 33, "Tous les frais, droits et honoraires des présents statuts et de leurs suites seront pris en charge par la société."]
];
/* ============================================================
   SECTION NOTAIRES : socle commun et quatre modèles
   N1 Statuts, un gérant        N2 Statuts, co-gérance
   N3 Déclaration notariée de souscription et de versement
   N4 Mise à jour des statuts avec cession de parts
   ============================================================ */
const NOTAIRE_DEF={notaire_nom:'',notaire_sign:'',notaire_ville:'',notaire_ref:'',notaire_genre:'F'};
const NOTAIRE_KEYS=Object.keys(NOTAIRE_DEF);
function notaireProfile(){
  try{const o=JSON.parse(localStorage.getItem('juriskpro:notaire:v1')||'null');return Object.assign({},NOTAIRE_DEF,o||{});}
  catch(e){return Object.assign({},NOTAIRE_DEF);}
}
function saveNotaireProfile(S){
  try{const o={};NOTAIRE_KEYS.forEach(k=>{if(S[k]!=null) o[k]=S[k];});localStorage.setItem('juriskpro:notaire:v1',JSON.stringify(o));}catch(e){}
}
const NSIT=[{v:'celibataire',t:'Célibataire'},{v:'marie',t:'Marié(e)'},{v:'divorce',t:'Divorcé(e)'},{v:'veuf',t:'Veuf(ve)'}];
const NPIECE={
  cni:{t:'de la Carte Nationale d’Identité',e:'e',l:'Carte nationale d’identité'},
  passeport:{t:'du Passeport',e:'',l:'Passeport'},
  sejour:{t:'de la Carte de résident',e:'e',l:'Carte de résident'},
  attestation:{t:'de l’Attestation d’identité',e:'e',l:'Attestation d’identité'}
};
const nAssoc=S=>clamp(parseInt(S.nb_assoc,10)||2,2,8);
const NIDKEYS=['civilite','prenom','nom','profession','naissance_lieu','naissance_date','nationalite','ville','commune','quartier','bp','situation','conj','mar_lieu','mar_mairie','mar_date','regime','piece_type','piece_num','piece_lieu','piece_date','piece_exp'];
function nItemDefaults(){return {civilite:'M.',nationalite:'Ivoirienne',ville:'ABIDJAN',situation:'celibataire',regime:'communaute',piece_type:'cni'};}
function nSrcOptions(S){
  const n=nAssoc(S),o=[];
  for(let i=0;i<n;i++) o.push({v:'a'+i,t:'Associé '+(i+1)+' : '+personName(S,'a',i).replace(/^Associé \d+$/,'à renseigner')});
  o.push({v:'autre',t:'Une autre personne'});
  return o;
}

